1	using MapEdit;
2	using Microsoft.Xna.Framework;
3	using ProjectTower.texturesheet;
5	namespace ProjectTower.particles.particles.debris;
7	internal class GolemFire : BaseParticle
8	{
9		public override void Init(Particle p, Vector2 loc, Vector2 traj, float size, float rotation, int flags, int owner)
10		{
11			p.loc = loc;
12			p.traj = traj;
13			p.size = size;
14			p.rotation = rotation;
15			p.flags = Rand.GetRandomInt(1, 9);
16			p.owner = owner;
17			p.frame = Rand.GetRandomFloat(0.3f, 0.7f);
18			p.rDir = Rand.GetRandomFloat(-9f, 9f);
19			p.rotation = Trig.GetAngle(p.traj, default);
20			base.Init(p, loc, traj, size, rotation, flags, owner);
21		}
23		public override void Update(Particle p, float frameTime)
24		{
25			TrimFrame(p);
26			float frame = p.frame;
27			p.rotation += p.rDir * frameTime;
28			base.Update(p, frameTime);
29			if (p.exists && (int)(p.frame * 30f) != (int)(frame * 30f) && Rand.CoinToss(0.25f))
30			{
31				p.traj.X += Rand.GetRandomFloat(-100f, 120f);
32				p.traj.Y += Rand.GetRandomFloat(-100f, 80f);
33				p.rotation = Trig.GetAngle(p.traj, default);
34			}
35		}
37		public override void Draw(Particle p, float brite)
